import {writeFileSync} from 'node:fs';
import {createAnalysisSampleDocument} from '../../../src/components/analysis/analysisSample.ts';
import {createFitYByXAnalysisDocument} from '../../../src/components/analysis/adapters/fitYByXAnalysisAdapter.ts';
import {createFitModelAnalysisDocument} from '../../../src/components/analysis/adapters/fitModelAnalysisAdapter.ts';
import {createHypothesisTestAnalysisDocument} from '../../../src/components/analysis/adapters/hypothesisTestAnalysisAdapter.ts';
import {createDefaultFitYByXGraphConfig} from '../../../src/components/fitYByX/fitYByXConfig.ts';
import {useGraphBuilderNewStore} from '../../../src/stores/useGraphBuilderNewStore.ts';
const createdAt='2026-10-30T00:00:00.000Z';
const response={columnId:'@value',name:'value',type:'continuous' as const};
const factor={columnId:'@factor',name:'factor',type:'continuous' as const};
const distribution=createAnalysisSampleDocument({datasetId:'@table',analysisId:'distribution',analysisName:'Distribution',createdAt});
if(distribution.analysisKind==='distribution')distribution.definition.responses=[response];
const fitY=createFitYByXAnalysisDocument({item:{id:'fit-y',name:'Fit Y by X',sourceDatasetId:'@table',response,factor,personality:'bivariate',graph:createDefaultFitYByXGraphConfig({response,factor}),createdAt},confidenceLevel:0.95,updatedAt:createdAt});
const fitModel=createFitModelAnalysisDocument({item:{id:'fit-model',name:'Fit Model',sourceDatasetId:'@table',response,construct:{kind:'manual'},terms:[{kind:'main',columnNames:['factor']}],centeringMethod:'mean',createdAt},confidenceLevel:0.95,updatedAt:createdAt});
const hypothesis=createHypothesisTestAnalysisDocument({id:'hypothesis',name:'Hypothesis Test',sourceDatasetId:'@table',createdAt,definition:{kind:'hypothesisTest',roles:{layout:'long',response,condition:{columnId:'@group',name:'grp',type:'nominal'},subject:null},studyDesign:'independent',selectionMode:'automatic',manualSelection:null,alternative:'twoSided',alpha:0.05,confidenceLevel:0.95,levelOrder:['A','B'],referenceLevel:'A',postHoc:'automatic',selectorVersion:'1'}});
const graphId=useGraphBuilderNewStore.getState().open('@table',0);
useGraphBuilderNewStore.getState().addLayer(graphId,'line');
const graph={...useGraphBuilderNewStore.getState().items[0],id:'graph-new',name:'Graph',xColumnId:'@factor',yColumnId:'@value',overlayColumnId:'@group',hiddenOverlayGroupIds:['sha256:'+'a'.repeat(64)],camera:{xMin:0,xMax:10,yMin:0,yMax:50}};
graph.layers=graph.layers.map((layer,index)=>({...layer,id:`layer-${index}`}));
writeFileSync(new URL('./documents.json',import.meta.url),JSON.stringify([distribution,fitY,fitModel,hypothesis,graph],null,2)+'\n');
console.log('Created stable document fixtures from existing analysis and graph factories.');
